function hintForLegacy(){if(!f().rearBagMoved)return ['경고는 운전석 벨트만의 문제가 아니다. 뒷좌석을 살펴보자.','외투 아래의 물건에 벨트가 걸려 있다. 좌석은 무게를 감지한다.','외투를 치우고 가방의 벨트를 푼 뒤 바닥으로 옮기자. 가방 안을 조사한다.'];if(!f().readerCollected)return ['조수석의 서랍에는 자물쇠가 보이지 않는다.','글로브박스를 열고 내부 물건을 살펴보자.','서랍에서 리더기와 안내서 B를 챙긴다. 카드+리더기, 안내서 A+B를 각각 조합할 수 있다.'];if(!f().messageRead&&v().seatPosition<99)return ['뒷유리의 손가락 자국은 빗물이 아니라 실내 쪽 흔적이다.','공조 조건을 바꾸면 유리에 김을 만들 수 있다. 거울로 문양을 읽어 보자.','A/C OFF, 내기 ON, 26°C 이상, 송풍 1단 이상을 5초 유지. 미러를 오른쪽으로 조금 돌리면 문장이 읽힌다.'];if(!f().seatToolCollected)return ['시트 레일은 현재 위치에서 끝나지 않는다.','운전석을 앞으로 끝까지 보낸 뒤 뒤쪽 아래를 조사한다.','운전석 하단의 시트 조절을 100% 앞쪽으로 옮기고 레일 사이의 삼각 도구를 챙긴다.'];if(!f().manualAssembled)return ['두 장의 안내서와 선바이저의 테두리에 같은 점선이 있다.','A+B를 맞추고 선바이저 접기 표시와 조합한다.','왼쪽 1/3을 안으로 접고, 아래 1/3을 위로 접는다. 반시계 90° 다음 시계 180°가 드러난다.'];if(!f().roofUnlocked)return ['조명 뒤의 점검 커버와 도구에 같은 삼각 기호가 있다.','소지품에서 도구를 선택한 뒤 천장 커버의 소켓에 사용한다.','커버를 열고 도구를 끼운다. 반시계 90° → 시계 180°로 돌린 뒤 선루프를 밀어 연다.'];return ['머리 위 잠금이 풀렸다.','선루프를 밀어 열 수 있다.','천장으로 가서 선루프 개방 후 차 밖으로 나간다.'];}
