function showMenu(){showModal('일시정지',`<div class="menu-list"><button id="menu-notes" class="action">${icon('book')}수첩</button><button id="menu-evidence" class="action">${icon('search')}현재 화면 조사 목록</button><button id="menu-display" class="action">${icon('settings')}화면·소리 설정</button><button id="menu-new" class="action danger">${icon('restart')}새 게임</button></div><p class="subtle" style="margin-top:22px">획득과 해독은 자동 저장됩니다. 현재 회전·접기의 미완료 단계는 재실행 시 처음으로 돌아갑니다.</p><p class="subtle">플레이 시간 ${formatTime(game.state.elapsedSec)} · 힌트 ${game.state.metrics.hints}회</p>`,[{label:'이어서 플레이',primary:true,run:()=>closeModal()}],'menu','PAUSED / PROGRESS SAVED');$('#menu-notes').onclick=showNotebook;$('#menu-display').onclick=showSettings;$('#menu-new').onclick=confirmNewGame;$('#menu-evidence').onclick=showSceneList;}
