async function audioBuffer(name){if(effectBuffers.has(name))return effectBuffers.get(name);const data=u('assets/audio/'+name+'.wav');let array;if(data.startsWith('data:')){const raw=atob(data.split(',')[1]);array=Uint8Array.from(raw,c=>c.charCodeAt(0)).buffer}else{const response=await fetch(data);array=await response.arrayBuffer()}const buffer=await audioContext.decodeAudioData(array.slice(0));effectBuffers.set(name,buffer);return buffer;}
async function ensureAudio(){if(externalPause)throw new Error('PAUSED');if(!audioContext)audioContext=new(window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')await audioContext.resume();return audioContext;}
async function effect(name,volume=1){if(muted||externalPause)return;try{await ensureAudio();const buffer=await audioBuffer(name);if(muted||externalPause)return;const s=audioContext.createBufferSource(),gain=audioContext.createGain();s.buffer=buffer;gain.gain.value=.55*volume;s.connect(gain).connect(audioContext.destination);s.start()}catch{}}
