async function playRecording(fromStart=false){
 if(!f().usbConnected)return;try{await ensureAudio();if(!recordingBuffer)recordingBuffer=await audioBuffer('stereo-recording');stopRecording();game.a.duration=recordingBuffer.duration;if(!game.startAudio(fromStart))return;
 recordSource=audioContext.createBufferSource();recordSource.buffer=recordingBuffer;const split=audioContext.createChannelSplitter(2);leftGain=audioContext.createGain();rightGain=audioContext.createGain();merger=audioContext.createChannelMerger(2);recordSource.connect(split);split.connect(leftGain,0);split.connect(rightGain,1);leftGain.connect(merger,0,0);rightGain.connect(merger,0,1);merger.connect(audioContext.destination);applyBalance();recordingStartedAt=audioContext.currentTime;recordingStartedPos=game.a.position;recordSource.start(0,game.a.position);recordSource.onended=()=>{if(game.runtime.playing){const left=f().audioLeftDecoded,right=f().audioRightDecoded;game.advanceAudio(Math.max(0,game.a.duration-game.a.position));if(!left&&f().audioLeftDecoded||!right&&f().audioRightDecoded){effect('collect');save()}paintAudio();}};paintAudio();
 }catch(e){game.runtime.playing=false;toast('녹음을 재생하지 못했습니다. 파일을 다시 열거나 다른 브라우저에서 확인해 주세요.');paintAudio();}}
