function setHostStateLegacy(update={}){host={...host,...update,insets:{...host.insets,...(update.insets||{})}};const blocked=!host.parked||!host.visible||host.obscured;if(blocked){externalPause=true;$('#paused-screen').style.display='flex';$('#pause-reason').textContent=!host.parked?'주차 상태에서 다시 이어서 플레이할 수 있습니다.':host.obscured?'시스템 화면이 닫히면 같은 장면에서 이어갑니다.':'화면으로 돌아오면 같은 장면에서 이어갑니다.';$('#resume-game').disabled=true;setGameInert(true);$('#modal').inert=true;}else if(externalPause){$('#resume-game').disabled=false;$('#pause-reason').textContent='준비되면 같은 장면에서 이어서 플레이하세요.';}for(const key of ['top','right','bottom','left'])$('#app').style['padding'+key[0].toUpperCase()+key.slice(1)]=Math.max(0,Number(host.insets[key])||0)+'px';syncPaused();save();fitWorld();}
