let profileNow=null;
function setProfile(id){profileNow=PROFILES.find(p=>p.id===id)||null;const app=$('#app');if(!profileNow){Object.assign(app.style,{width:'100%',height:'100dvh',transform:'none',transformOrigin:'top left',position:'relative'});Object.assign(document.body.style,{width:'100%',height:'100%',overflow:'hidden'});fitWorld();return}const [w,h]=profileNow.windowDp,scale=Math.min(1,window.innerWidth/w,window.innerHeight/h);Object.assign(app.style,{width:w+'px',height:h+'px',transform:`scale(${scale})`,transformOrigin:'top left',position:'absolute'});toast(profileNow.label+' · '+w+'×'+h+'dp · 축소 검토 '+Math.round(scale*100)+'%');fitWorld();}
