let buildMode='DEVELOPMENT',terminalRefresh=null,archivePlayer=null,devSafetyEnabled=true,deviceExplained=new Set(),activeInputView=null;
const chapterNames={1:'차 안에 남은 흔적',2:'누락된 다섯 번째 기록',3:'마지막 시동'};
const inputNames={P01:'앞유리 관찰',P05:'유리 흔적 복원',P08:'감시 영상 복원',P09:'장부 층 복원',P12:'프레임 주 잠금',P13:'상하 회로 판독',P14:'출구 경로 복원'};
function renderWorld(){renderWorldLegacy();refreshNav();const s=screen();$('#scene-code').textContent=String(game.state.chapter).padStart(2,'0')+'막 / '+s.id;$('.residual-status').textContent=buildMode==='DEVELOPMENT'?'개발용 · 가상 정차':'정차 신호 확인';const b=$('#input-button');if(b){b.hidden=!game.state.screenControlAssist;b.setAttribute('aria-label','차량 입력 · 화면 조작 보조');}if(s.chapter>1){const plates={S07:[430,285,225,140],S08:[537,234,589,275],S09:[644,284,434,171],S10:[653,332,496,214],S11:[848,534,328,128],S12:[485,249,680,230],S13:[1000,344,447,164],S14:[767,489,449,131]},p=plates[s.id];if(p){const status=game.f.gameComplete?'COMPLETE':s.chapter===2?'ARCHIVE / LOCAL':'FRAME / LOCAL';const group=document.createElementNS('http://www.w3.org/2000/svg','g');group.setAttribute('class','world-art terminal-plate');group.setAttribute('aria-hidden','true');const [x,y,w,h]=p;group.innerHTML=`<path d="M${x} ${y+h*.5}h${w}" stroke="#7faeaa" opacity=".25"/><text x="${x+24}" y="${y+34}" fill="#d3b67f" font-size="13" letter-spacing="3">${status}</text><text x="${x+24}" y="${y+84}" fill="#bbd4ce" font-size="22">${esc(s.id==='S07'?'감시 영상':s.subtitle)}</text><text x="${x+24}" y="${y+h-18}" fill="#6c9292" font-size="14">${s.id} / 조사하여 기록 열기</text>`;$('#world-svg').append(group);}}
}
function refreshNav(){const scenes=CONTENT.scenes.filter(s=>s.chapter===game.state.chapter),nav=$('#view-nav');if(nav.dataset.chapter!==String(game.state.chapter)){nav.dataset.chapter=game.state.chapter;nav.innerHTML=scenes.map((s,i)=>`<button class="view-tab" data-scene="${s.id}"><small>${i+1}</small>${esc(s.name)}</button>`).join('');$$('#view-nav [data-scene]').forEach(b=>b.onclick=()=>sceneTo(b.dataset.scene));}$$('.view-tab').forEach(b=>{b.classList.toggle('current',b.dataset.scene===game.state.currentScreen);b.setAttribute('aria-current',b.dataset.scene===game.state.currentScreen?'true':'false')});}
function explainDevice(label,next){if(deviceExplained.has(label)){next();return}deviceExplained.add(label);showModal('게임 전용 장치',`<p><strong>${esc(label)}</strong>는 화면 속에서 조사하고 조작하는 장치입니다.</p><p>운전석이나 조수석에 앉은 채 터치로 진행할 수 있습니다.</p>`,[{label:'장치 조사하기',primary:true,run:next}],'device','GAME DEVICE');}
function interact(id){if(externalPause||endingActive)return;const handlers={surveillance:showFilm,filmDesk:showFilm,surveillanceNote:()=>showMemo('감시실 작업 메모','영상의 빗물 층은 작동 신호에서 잡힌다. 정지하면 가려진 시각이 남는다. 빈자리가 먼저였는지, 차가 먼저였는지 확인할 것.'),ledgerTerminal:showLedger,ledgerBook:showOriginalLedger,filmReader:showLedger,archive:showArchive,tapes:showArchive,archiveNote:()=>showMemo('원본 채널 표식','L은 02:05, R은 02:17. 조각의 출처를 섞지 말 것. 녹음 마지막에 빗물 기호가 남아 있다.'),transmission:showManifest,photoBoard:showPhotos,recoveryBox:showRecovery,returnTerminal:showReturn,latches:showReturn,returnNote:()=>showMemo('내가 남긴 표시','이 토큰은 프레임 04용이다. 지운 흔적을 다시 드러내고, 멈춘 자리에서 연결선을 확인한다. 손은 이 순서를 알고 있다.'),circuitTerminal:showCircuit,circuitSlots:showCircuit,gateTerminal:showGate,gateSlot:showGate,gateShutter:()=>toast(f().gateAuthorized?'승인된 출구다. 차량 대시보드로 돌아가자.':'출구 단말기의 경로 승인이 필요하다.'),dashboard:showDashboard,keySlot:showDashboard,startButton:showDashboard};if(handlers[id]){handlers[id]();return}if(id==='wiper'){showInputPuzzle('P01','앞유리의 물막','멈춘 상태에서 시작해 와이퍼가 작동하면 물막 사이로 외부 표식이 드러날 것 같다.',()=>{closeModal();renderWorld();});return}if(id==='climate'){showMedia();return}if(id==='audio'){explainDevice('녹음 재생기',showAudio);return}if(id==='mirror'){explainDevice('룸미러',()=>{if(game.state.currentScreen!=='S04')sceneTo('S04');showMirror();});return}if(['seat','roof','cover'].includes(id)&&!deviceExplained.has(id)){explainDevice(id==='seat'?'시트 레일':id==='roof'?'선루프':'천장 점검 장치',()=>{deviceExplained.add(id);interactLegacy(id)});return}interactLegacy(id);}
function showMemo(title,text){showModal(title,`<article class="note narrative-note"><p>${esc(text)}</p></article>`,[],'memo','FIELD NOTE');}
function showBelt(){showModal('게임 계기판',`<p>내 차는 운송 프레임에 고정돼 있다. 보조 전원만 살아 있고 열쇠는 보이지 않는다.</p><p>뒤쪽 좌석에 외투와 무거운 가방이 놓여 있다.</p>`,[{label:'뒷좌석 조사',primary:true,run:()=>sceneTo('S03')}],'cluster','M—04 / STATUS');}
function showMedia(){showModal('게임 미디어 화면',`<p>보조 전원으로 기록 재생기와 흔적 판독부가 살아 있다.</p><div class="menu-list"><button id="v2-audio" class="action">녹음 재생기</button><button id="v2-fog" class="action">유리 흔적 판독</button></div><p class="subtle">USB ${f().usbConnected?'연결됨':'연결 대기'}</p>`,[],'media');$('#v2-audio').onclick=()=>explainDevice('녹음 재생기',showAudio);$('#v2-fog').onclick=showClimate;}
function showClimate(){showInputPuzzle('P05','유리에 남은 손자국','낮고 부드러운 바람이 유리 표면의 흔적을 드러낸다. 판독 뒤에는 게임 룸미러에서 각도를 맞춰 보자.',()=>{sceneTo('S04');showMirror();});}
function armTerminal(id){if(!game.input.armed||game.input.armed.id!==id)game.arm(id);}
function inputControls(){
 if(!game.state.screenControlAssist)return `<div class="readonly-status">실제 차량 상태 읽기 전용 · <span data-input-status>${esc(game.input.status)}</span></div>`;
 const key=game.input.armed&&ResidualRules.SEQUENCES[game.input.armed.id]?.[0];
 if(!key)return `<div class="read-status" data-input-idle>${activeInputView?'입력 복원을 마쳤습니다. 단서 화면으로 돌아가 결과를 조사하세요.':'아직 활성화한 장치가 없습니다. 장면 속 장치를 먼저 조사해 주세요.'}</div>`;
 const choices=key==='wiper'?[['OFF','정지'],['ACTIVE','작동']]:[['LOW','낮음'],['MID','중간']];
 return `<div class="sim-input" data-simulation-panel><div class="eyebrow">SIMULATION / 화면 조작 보조 ON</div><p class="subtle">게임 전용 입력 · 실제 차량 설정에는 반영되지 않습니다.</p><div class="input-row"><strong>${key==='wiper'?'와이퍼':'풍량'}</strong>${choices.map(([value,label])=>`<button class="action ${game.input.values[key]===value?'chosen':''}" aria-pressed="${game.input.values[key]===value}" data-signal="${key}:${value}">${label}</button>`).join('')}</div><div class="input-feedback" role="status" aria-live="polite" data-input-status>${esc(game.input.status)}</div><div class="input-meter"><i data-input-meter></i></div></div>`;
}
function wireInput(){
 if(!game.state.screenControlAssist)return;
 $$('[data-signal]').forEach(b=>b.onclick=()=>{
  if(externalPause||game.runtime.paused)return;
  const [key,value]=b.dataset.signal.split(':');
  if(game.input.receive(game.input.packet(key,value)))effect(key==='wiper'?'wiper':'latch',.2);
  $$('[data-signal]').forEach(x=>{const [k,v]=x.dataset.signal.split(':');const chosen=game.input.values[k]===v;x.classList.toggle('chosen',chosen);x.setAttribute('aria-pressed',String(chosen));});
  updateInputStatus();
 });
}
function updateInputStatus(){const s=$('[data-input-status]');if(s&&s.textContent!==game.input.status)s.textContent=game.input.status;const meter=$('[data-input-meter]');if(meter)meter.style.width=game.input.pending?Math.min(100,(Date.now()-game.input.pending.since)/7)+'%':'0%';}
function inputButton(){return game.state.screenControlAssist?`<button id="open-input-panel" class="action">화면 조작 보조 입력</button>`:'';}
function showInputPuzzle(id,title,description,next){activeInputView={id,screenId:game.state.currentScreen,render:()=>showInputPuzzle(id,title,description,next)};const done={P01:f().wiperObserved,P05:f().fogMessageVisible}[id];if(!done)armTerminal(id);showModal(title,`<p>${esc(description)}</p>${done?'<p class="read-status decoded">흔적을 복원했습니다. 장면에서 단서를 조사할 수 있습니다.</p>':inputControls()}`,done?[{label:id==='P01'?'앞유리 조사':'게임 룸미러 조사',primary:true,run:next}]:[],'input-puzzle',id+' / OBSERVATION');if(!done){wireInput();terminalRefresh=()=>showInputPuzzle(id,title,description,next);}else terminalRefresh=null;}
function showInputPanel(){
 const view=activeInputView?.screenId===game.state.currentScreen?activeInputView:null;
 showModal('차량 입력 · 화면 조작 보조',`<p>${esc(view?inputNames[view.id]:game.input.armed?inputNames[game.input.armed.id]:'장면 속 장치에서 입력을 시작합니다.')}</p>${inputControls()}`,view?[{label:'단서 화면으로 돌아가기',primary:true,run:()=>view.render()}]:[],'input-panel','DEVELOPMENT / SIMULATION');wireInput();
}
function terminal(id,title,desc,body,actions=[],refresh){if(ResidualRules.SEQUENCES[id])activeInputView={id,screenId:game.state.currentScreen,render:refresh};showModal(title,`<p>${desc}</p>${body}`,actions,'terminal',id+' / '+chapterNames[game.state.chapter]);terminalRefresh=refresh;wireInput();}
function showFilm(){if(!f().rainSequenceDone)armTerminal('P08');let order=[];terminal('P08','감시 영상 · 누락된 05','이 시설 단말은 M-04의 진단 입력으로 기록 층을 읽는다. 현실에서는 주차된 좌석에서 계속 플레이한다. 메모: “작동 신호로 빗물 층을 잡고, 멈춰 시각을 남겨라.” 두 장면의 앞뒤를 복원해야 한다.',f().rainSequenceDone?`<div class="film-grid">${[['04','02:17','차량이 반입된다.'],['05','02:05','프레임이 비어 있다.']].map(([id,t,cap])=>`<button class="film-card" data-film="${id}"><div class="film-picture"><img src="${u('assets/backgrounds/film-'+id+'.png')}" alt="운송 프레임 영상"><span>${id}</span></div><strong>${t} / FRAME ${id}</strong><p>${cap}</p></button>`).join('')}</div><div id="film-order" class="selection-order">시간 순서대로 장면을 선택하세요.</div><button id="film-reset" class="action">순서 지우기</button>${f().diagnosticStrip?'<p class="read-status decoded">영상 순서를 기록했습니다. 진단실로 이어집니다.</p>':''}`:inputControls(),f().rainSequenceDone?[{label:'영상 순서 확정',primary:true,run:()=>{const r=act('filmOrder',order);if(r.changed)showFilm();}},{label:'진단 기록으로',run:()=>sceneTo('S08')}]:[],showFilm);if(f().rainSequenceDone){$$('[data-film]').forEach(b=>b.onclick=()=>{if(!order.includes(b.dataset.film)&&order.length<2)order.push(b.dataset.film);$('#film-order').textContent=order.map(x=>'FRAME '+x).join(' → ');});$('#film-reset').onclick=()=>{order=[];$('#film-order').textContent='시간 순서대로 장면을 선택하세요.';};}}
const originalRows=[['M01','01:28','M-01','반입','A / ◇ 01'],['M03','01:56','M-03','반입','B / ○ 03'],['M05-0205','02:05','M-05','출구 대기','윤서 / 공란'],['M04','02:17','M-04','반입','C / △ 04']];
const modifiedRows=[['M01-edit','01:28','M-01','반입'],['M03-edit','01:56','M-03','반입'],['M04-edit','02:17','M-04','반입'],['M05-0218','02:18','M-05','인계 완료']];
function ledgerTable(rows,attr){return `<div class="ledger-table">${rows.map(([id,time,car,state,mark])=>`<button class="ledger-row" ${attr?`data-${attr}="${id}"`:''}><span>${time}</span><strong>${car}</strong><span>${state}</span>${mark?`<small>${mark}</small>`:''}</button>`).join('')}</div>`;}
function showOriginalLedger(){if(!f().falsificationFound){showMemo('보관 장부','원본은 진단 단말기의 낮은 풍량 층에, 수정 이력은 그 다음 중간 풍량 층에 남아 있다. 영상 진단 스트립과 대조해야 한다.');return}showModal('원본 반입 장부',`<div class="art-figure paper"><img src="${u('assets/documents/original-ledger.svg')}" alt="원본 장부. A M01, B M03, C M04. M05는 02시05분 출구 대기."></div>`,[],'ledger');}
function showLedger(){if(!f().diagnosticStrip){showMemo('진단 스트립 대기','감시실의 영상 순서를 복원하면 원본 장부를 판독할 진단 스트립을 얻을 수 있다.');return}if(!f().ledgerLayersSeen)armTerminal('P09');const first=game.input.armed?.id==='P09'&&game.input.step>=1;let original=null,modified=null;terminal('P09','원본과 수정본','작업 메모: “낮은 바람에서 원본을 고정하고, 다음 풍량에서 덮어쓴 기록을 읽는다.” 같은 구역에서 바뀐 행을 서로 연결한다.',`<div class="ledger-columns"><section><h3>원본 / LOW</h3>${first||f().ledgerLayersSeen?ledgerTable(originalRows,'original'):'<div class="locked-layer">원본 층 입력 대기</div>'}</section><section><h3>수정 / MID</h3>${f().ledgerLayersSeen?ledgerTable(modifiedRows,'modified'):'<div class="locked-layer">수정 층 입력 대기</div>'}</section></div>${!f().ledgerLayersSeen?inputControls():`<p id="ledger-selection" class="selection-order">대조할 원본 행과 수정 행을 각각 선택하세요.</p>${f().falsificationFound?'<p class="read-status decoded">조작된 M-05 기록과 녹음 조각을 확보했습니다.</p>':''}`}`,f().ledgerLayersSeen?[{label:'선택한 두 행 연결',primary:true,run:()=>{const r=act('ledgerLink',{original,modified});if(r.changed)showLedger();}},{label:'음성 기록실로',run:()=>sceneTo('S09')}]:[],showLedger);$$('[data-original],[data-modified]').forEach(b=>b.onclick=()=>{if(b.dataset.original){original=b.dataset.original;$$('[data-original]').forEach(x=>x.classList.toggle('chosen',x===b));}else{modified=b.dataset.modified;$$('[data-modified]').forEach(x=>x.classList.toggle('chosen',x===b));}if($('#ledger-selection'))$('#ledger-selection').textContent=`원본 ${original||'미선택'} ↔ 수정 ${modified||'미선택'}`;});}
function waveSelect(slot){return `<label class="puzzle-field"><span>${slot} / 원본 채널 슬롯</span><select id="wave-${slot}" aria-label="${slot} 채널 조각"><option value="">조각 선택</option><option value="waveRight">조각 R · 02:17</option><option value="waveLeft">조각 L · 02:05</option></select></label>`;}
function showArchive(){if(!f().falsificationFound){showMemo('음성 기록실','장부의 수정 이력을 찾아 원본 녹음 조각을 확보해야 한다.');return}terminal('P10','원본 음성 복원','원본 표식이 같은 슬롯에 녹음 조각을 넣는다. 두 출처를 확인한 뒤 지시의 선후를 정하자.',!f().wavePlaced?`<div class="wave-fragments"><img src="${u('assets/documents/wave-left.svg')}" alt="조각 L / 02:05"><img src="${u('assets/documents/wave-right.svg')}" alt="조각 R / 02:17"></div><div class="two-col">${waveSelect('L')}${waveSelect('R')}</div>`:`<div class="archive-console"><div class="waveform archive-wave">${Array.from({length:60},(_,i)=>`<i style="height:${8+Math.abs(Math.sin(i*2.7)*Math.cos(i*.7))*82}%"></i>`).join('')}</div><div class="channel-actions"><button class="action" data-archive="L">L 채널 듣기</button><button class="action" data-archive="R">R 채널 듣기</button></div><div class="caption-box" id="archive-caption">원본 채널을 선택하세요. 소리 없이도 자막으로 해독할 수 있습니다.</div><div class="channel-actions"><button class="action" data-transcript="L">L 원문 읽기</button><button class="action" data-transcript="R">R 원문 읽기</button></div><p id="archive-read-flags" class="subtle">L ${f().archiveLeftRead?'확인':'미확인'} / R ${f().archiveRightRead?'확인':'미확인'}</p></div>`,!f().wavePlaced?[{label:'두 조각 배치 확정',primary:true,run:()=>{const r=act('wavePlace',{L:$('#wave-L').value,R:$('#wave-R').value});if(r.changed)showArchive();}}]:[{label:'명단 송신 → 회수함 조사',primary:true,run:()=>{const r=act('archiveOrder','sendThenRecover');if(r.changed)sceneTo('S10');}},{label:'회수함 조사 → 명단 송신',run:()=>act('archiveOrder','recoverThenSend')}],showArchive);const read=(side,listen)=>{if(!listen&&archivePlayer)archivePlayer.pause();act('archiveRead',side,{quiet:true,redraw:false});const text=side==='L'?'“05는 비어 있어. 명단부터 보내.”':'“키는 인계가 아니라 회수.”';$('#archive-caption').innerHTML=`<div class="caption-channel">${side} / ORIGINAL SOURCE</div><p>${text}</p><p class="subtle">${side==='R'?'녹음 끝: “두 번 남기고 멈춰.”':'원본 L 기록을 확인했습니다.'}</p>`;$('#archive-read-flags').textContent=`L ${f().archiveLeftRead?'확인':'미확인'} / R ${f().archiveRightRead?'확인':'미확인'}`;if(listen)playArchive(side);};$$('[data-archive]').forEach(b=>b.onclick=()=>read(b.dataset.archive,true));$$('[data-transcript]').forEach(b=>b.onclick=()=>read(b.dataset.transcript,false));}
async function playArchive(side){if(externalPause)return;if(archivePlayer){archivePlayer.pause();archivePlayer=null;}try{archivePlayer=new Audio(u('assets/audio/archive-'+side+'.wav'));archivePlayer.muted=muted;await archivePlayer.play();}catch{toast('자막으로 원본을 읽을 수 있습니다.');}}
function photoCards(){return `<div class="photo-grid">${[['A','◇ 01'],['B','○ 03'],['C','△ 04']].map(([letter,mark])=>`<article class="evidence-photo"><img src="${u('assets/items/victim'+letter+'.png')}" alt="구조 대상 사진 ${letter}"><div class="photo-back"><strong>사진 ${letter}</strong><span>뒷면 화물 표식 ${mark}</span></div></article>`).join('')}</div>`;}
function showPhotos(){showModal('사진 뒷면의 화물 표식',`${photoCards()}<p>화물 표식은 원본 반입 장부의 식별 칸과 이어진다. 사람의 이름 대신 프레임 번호로 기록돼 있다.</p>`,[{label:'명단 단말기로',primary:true,run:showManifest}],'photos','EVIDENCE / A · B · C');}
function carSelect(letter){return `<label class="puzzle-field"><span>사진 ${letter}의 프레임</span><select id="manifest-${letter}" aria-label="사진 ${letter} 프레임"><option value="">선택</option>${['M-01','M-02','M-03','M-04','M-05'].map(x=>`<option>${x}</option>`).join('')}</select></label>`;}
function showManifest(){if(!f().recoveryLocation){showMemo('명단 송신 단말기','윤서의 두 원본 채널을 확인해 다음 행동을 정해야 한다.');return}terminal('P11','구조 명단 송신','사진 뒷면의 화물 표식과 원본 반입 장부를 대조한다. 윤서의 M-05 수정 이력도 함께 보내야 한다.',`${photoCards()}<details class="dossier"><summary>원본 반입 장부 펼치기</summary>${ledgerTable(originalRows)}</details><div class="manifest-fields">${['A','B','C'].map(carSelect).join('')}</div><label class="attach-check"><input type="checkbox" id="attach-history">윤서 · M-05 원본/수정 이력 첨부</label><p class="subtle">게임 내부의 가상 송신입니다.</p>${f().manifestSent?'<p class="read-status decoded">명단 접수 확인. 회수함 잠금이 해제됐습니다.</p>':''}`,[{label:'명단 송신',primary:true,run:()=>{const r=act('manifest',{A:$('#manifest-A').value,B:$('#manifest-B').value,C:$('#manifest-C').value,attach:$('#attach-history').checked});if(r.changed)showRecovery();}},{label:'회수함 조사',run:showRecovery}],showManifest);}
function showRecovery(){if(!f().manifestSent){showMemo('잠긴 회수함','명단 접수 확인을 기다리고 있다. 윤서의 말대로 송신이 먼저다.');return}showModal('열린 회수함',`<div class="recovery-items"><img src="${u('assets/items/smartKey.png')}" alt="스마트키"><img src="${u('assets/items/frameToken.png')}" alt="프레임 토큰"></div><p>키는 인계된 것이 아니라 이곳으로 회수돼 있었다. 토큰 모서리에는 프레임 04의 홈과 같은 모양이 있다.</p>`,[{label:'키와 토큰 챙기기',primary:true,run:()=>act('recovery')}],'recovery','CHAPTER 02 / RECOVERY');}
function showReturn(){if(!f().frameTokenInserted){showModal('프레임 토큰 판독기',`<div class="art-figure"><img src="${u('assets/items/frameToken.png')}" alt="프레임 토큰" style="max-height:230px"></div><p>차량에 돌아왔다. 이 판독기는 프레임 04에 맞는 토큰을 기다리고 있다.</p>`,[{label:'게임 프레임 토큰 삽입',primary:true,run:()=>{act('insertFrameToken');showReturn();}}],'return');return}if(!f().returnSequenceDone)armTerminal('P12');terminal('P12','프레임 주 잠금','내가 남긴 표시: “정지에서 흔적을 드러내고, 다시 멈춘 자리의 선을 따라.” 이번 단말기는 지금부터의 새 입력만 받는다.',!f().returnSequenceDone?inputControls():`<div class="latch-map"><svg viewBox="0 0 760 230" aria-label="위아래 연결선이 가운데 잠금쇠를 통과한다"><path d="M380 10V220 M90 100H670" stroke="#8ba4a0" stroke-width="8" fill="none"/><path d="M380 10V220" stroke="#d7b67c" stroke-width="12"/><path d="M90 75V130M670 75V130" stroke="#253f49" stroke-width="18"/></svg><div class="latch-buttons">${[['left','왼쪽'],['middle','가운데'],['right','오른쪽']].map(([id,label])=>`<button class="mechanical-latch action" data-latch="${id}">${label} 잠금쇠</button>`).join('')}</div></div>${f().framePrimaryReleased?'<p class="read-status decoded">주 잠금 해제. 프레임 진단으로 이동하세요.</p>':''}`,f().framePrimaryReleased?[{label:'프레임 진단으로',primary:true,run:()=>sceneTo('S12')}]:[],showReturn);$$('[data-latch]').forEach(b=>b.onclick=()=>{const r=act('latch',b.dataset.latch);if(r.changed)showReturn();});}
function circuitSvg(layer){const top=layer==='upper';return `<svg class="circuit-board" viewBox="0 0 620 270" aria-label="${top?'상단: 원과 삼각형':'하단: 사각형과 삼각형'} 접점"><path d="M40 ${top?60:210}H180V135H403V${top?60:210}H565" fill="none" stroke="${top?'#bf9a5e':'#70b6b6'}" stroke-width="9"/><circle cx="180" cy="135" r="29" fill="#172d36" stroke="${top?'#bf9a5e':'#70b6b6'}" stroke-width="5"/>${top?'<circle cx="180" cy="135" r="17" fill="none" stroke="#bda474" stroke-width="5"/>':'<rect x="163" y="118" width="34" height="34" fill="none" stroke="#80b8b6" stroke-width="5"/>'}<path d="M403 106L439 166H367Z" fill="#172d36" stroke="#d7b77c" stroke-width="6"/><text x="40" y="250" fill="#abc4c2" font-size="20">${top?'상단 / MID':'하단 / LOW'}</text></svg>`;}
function showCircuit(){if(!f().framePrimaryReleased){showMemo('프레임 진단','차량 귀환 장면에서 주 잠금을 먼저 해제해야 한다.');return}if(!f().circuitLayersSeen)armTerminal('P13');const upper=game.input.armed?.id==='P13'&&game.input.step>=1;terminal('P13','상하 회로 판독','단말기 각인: “중간 바람의 상단을 고정한 뒤, 낮은 바람의 하단을 겹쳐라.” 두 회로의 공통 접점을 이어야 한다.',`<div class="circuit-layers">${upper||f().circuitLayersSeen?circuitSvg('upper'):'<div class="locked-layer">상단 층 대기</div>'}${f().circuitLayersSeen?circuitSvg('lower'):'<div class="locked-layer">하단 층 대기</div>'}</div>${!f().circuitLayersSeen?inputControls():`<div class="node-actions">${[['circle','○ 원형'],['triangle','△ 삼각형'],['square','□ 사각형']].map(([id,label])=>`<button class="action" data-node="${id}">${label} 접점 연결</button>`).join('')}</div>${f().frameReleased?'<p class="read-status decoded">운송 프레임 해제. 출구 도면을 확보했습니다.</p>':''}`}`,f().frameReleased?[{label:'출구 단말기로',primary:true,run:()=>sceneTo('S13')}]:[],showCircuit);$$('[data-node]').forEach(b=>b.onclick=()=>{const r=act('circuit',b.dataset.node);if(r.changed)showCircuit();});}
function routeMap(){return `<svg class="route-map" viewBox="0 0 900 450" aria-label="출구 도면: A는 금색 층과 차단 구간, B는 청록 층과 차단 구간, C는 두 층이 겹치는 중앙 길"><defs><pattern id="map-grid" width="45" height="45" patternUnits="userSpaceOnUse"><path d="M0 45V0H45" fill="none" stroke="#45616a" stroke-width="1"/></pattern></defs><rect width="900" height="450" fill="url(#map-grid)"/><path d="M80 220H260V90H710V220H820 M80 220H260V360H710V220H820 M80 220H820" stroke="#57717a" stroke-width="22" fill="none"/><path d="M80 220H260V90H710V220H820 M80 220H820" stroke="#d1ad6b" stroke-width="7" fill="none"/><path d="M80 220H260V360H710V220H820 M80 220H820" stroke="#71c3c1" stroke-width="7" stroke-dasharray="14 7" fill="none"/><path d="M500 50V135M495 320V405" stroke="#bd6f56" stroke-width="18"/><g fill="#ebdcc0" font-size="28"><text x="420" y="65">A</text><text x="420" y="415">B</text><text x="420" y="200">C</text></g><circle cx="80" cy="220" r="17" fill="#d2b27b"/><circle cx="820" cy="220" r="17" fill="#7ebebe"/></svg>`;}
function showGate(){if(!f().gateDiagram){showMemo('출구 경로 대기','프레임 진단의 공통 접점을 연결해 출구 도면을 확보하자.');return}if(!f().gateSequenceDone)armTerminal('P14');terminal('P14','출구 경로 복원','윤서의 마지막 기호: “두 번 남기고 멈춰.” 도면에는 정지 표식 사이로 두 번의 작동 표시가 그려져 있다. 판독 후 두 기록 층과 개방 도면을 겹쳐 길을 고르자.',!f().gateSequenceDone?`<img class="gate-reference" src="${u('assets/documents/gate-diagram.svg')}" alt="정지, 빗방울, 정지, 빗방울, 정지 기호와 개방 통로">${inputControls()}`:`${routeMap()}<p class="map-legend"><span>금색: 첫 기록 층</span><span>청록: 두 번째 기록 층</span><span>적색: 차단 구간</span></p><div class="node-actions">${['A','B','C'].map(x=>`<button class="action" data-route="${x}">경로 ${x} 선택</button>`).join('')}</div>${f().gateAuthorized?'<p class="read-status decoded">경로 C 승인 · 출구 토큰 발급 완료</p>':''}`,f().gateAuthorized?[{label:'게임 대시보드로',primary:true,run:()=>sceneTo('S14')}]:[],showGate);$$('[data-route]').forEach(b=>b.onclick=()=>{const r=act('route',b.dataset.route);if(r.changed)showGate();});}
function showDashboard(){const checks=[['manifestSent','구조 명단 접수'],['frameReleased','운송 프레임 해제'],['gateAuthorized','출구 경로 승인'],['smartKeyCollected','스마트키 확보']];terminal('P15','마지막 시동','준비한 흔적은 모두 이 순간을 향해 있었다. 이제 화면 속 대시보드에서 마지막 확인을 마친다.',`<div class="dashboard-checks">${checks.map(([key,label])=>`<div class="dash-check ${f()[key]?'complete':''}"><i>${f()[key]?'✓':'—'}</i><span>${label}</span></div>`).join('')}</div><div class="dashboard-controls"><button id="insert-game-key" class="action" ${f().smartKeyInserted?'disabled':''}>${f().smartKeyInserted?'스마트키 삽입됨':'게임 스마트키 삽입'}</button><button id="confirm-game-token" class="action" ${f().tokenConfirmed?'disabled':''}>${f().tokenConfirmed?'출구 토큰 확인됨':'게임 출구 토큰 확인'}</button><button id="game-ignition" class="ignition-button" aria-label="게임 시동 걸기"><span>START</span><small>게임 시동</small></button></div><p class="subtle">화면 속 시동 연출입니다. 실제 차량을 움직일 필요가 없습니다.</p>`,[],showDashboard);$('#insert-game-key').onclick=()=>{const r=act('insertSmartKey');if(r.changed)showDashboard();};$('#confirm-game-token').onclick=()=>{const r=act('authorize');if(r.changed)showDashboard();};$('#game-ignition').onclick=()=>act('ignition');}
function showSettings(){showSettingsLegacy();const body=$('#panel .panel-body');body.insertAdjacentHTML('afterbegin',`<div class="settings-row"><span>화면 조작 보조</span><button id="screen-control-assist" class="action">${game.state.screenControlAssist?'ON · 가상 입력':'OFF · 실제 상태 읽기'}</button></div><p class="subtle">이 HTML은 개발용 시연본입니다. 실제 상태 읽기는 연결·권한·차종별 매핑·정차 검증을 통과해야 사용할 수 있습니다.</p>`);$('#screen-control-assist').onclick=()=>changeInputMode(!game.state.screenControlAssist);}
function changeInputMode(assist){const r=game.input.switchMode(assist);if(!r.ok){showModal('실제 차량 입력을 확인해야 합니다',`<p>현재 화면 조작 보조를 유지합니다.</p><ul>${r.errors.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`,[{label:'화면 조작 보조 ON 유지',primary:true,run:showSettings},{label:'다시 확인',run:()=>changeInputMode(false)}],'settings','CONNECTION CHECK');return}game.state.screenControlAssist=assist;terminalRefresh=null;save();renderWorld();showSettings();}
function hintFor(){if(game.state.chapter===1){if(!f().bagLooted)return ['뒷좌석 외투와 가방을 조사하자.','가방에 달린 고정 끈을 풀어 바닥으로 옮긴다.','외투 → 고정 끈 → 가방 이동 → 내용물 챙기기. 실제 안전벨트 조작은 없다.'];if(!f().readerCollected)return ['조수석 서랍은 잠겨 있지 않다.','리더기와 종이 B를 챙기고 인수 기록을 읽는다.','카드+리더기를 조합해 USB에 연결하고 종이 A+B도 맞춘다.'];if(!f().messageRead&&v().seatPosition<99)return ['미디어 화면의 유리 흔적 판독부를 조사하자.','낮은 풍량으로 흔적을 복원한 뒤 게임 룸미러 각도를 맞춘다.','풍량 낮음을 0.7초 유지하고 게임 룸미러를 오른쪽 14 부근에 맞춘다.'];return hintForLegacy().map(x=>x.replace('A/C OFF, 내기 ON, 26°C 이상, 송풍 1단 이상을 5초 유지.','풍량 낮음을 0.7초 유지.'));}if(game.state.chapter===2){if(!f().diagnosticStrip)return ['감시실 작업 메모를 읽어 보자.','와이퍼 작동 → 정지로 영상을 복원하고 빈 프레임 시각을 비교한다.','작동·정지를 각각 0.7초 유지한 뒤 05 → 04 순서로 영상을 확정한다.'];if(!f().falsificationFound)return ['진단실의 두 기록 층을 대조하자.','풍량 낮음 → 중간으로 원본과 수정본을 복원한다.','원본 02:05 M-05 출구 대기 ↔ 수정 02:18 M-05 인계 완료를 연결한다.'];if(!f().recoveryLocation)return ['음성 기록실에 원본 파형 조각을 넣자.','L/R 원본 표식에 맞춰 두 채널을 확인한다.','L조각은 L, R조각은 R. 명단 송신 → 회수함 조사 순서로 확정한다.'];return ['송신실 사진 뒷면과 원본 장부의 화물 표식을 비교하자.','A는 마름모01, B는 원03, C는 삼각04다.','A=M-01, B=M-03, C=M-04. M-05 수정 이력 첨부 후 송신하고 회수함을 연다.'];}if(!f().framePrimaryReleased)return ['차량 귀환 장면에서 프레임 토큰을 넣자.','새 입력 정지 → 작동 → 정지로 세 잠금쇠를 복원한다.','각 0.7초 유지한 뒤 연결선이 통과하는 가운데 잠금쇠를 선택한다.'];if(!f().frameReleased)return ['프레임 진단 단말기의 상하 층을 겹치자.','풍량 중간 → 낮음으로 두 층을 복원한다.','상하에 공통으로 나타나는 삼각 접점을 연결한다.'];if(!f().gateAuthorized)return ['출구 도면과 윤서의 마지막 기호를 다시 읽자.','정지 → 작동 → 정지 → 작동 → 정지. 실제 왕복 횟수가 아니라 상태 전환이다.','각 상태 0.7초 유지 후 두 기록 층과 개방 도면이 겹치는 경로 C를 고른다.'];return ['마지막 대시보드에서 준비 상태를 확인하자.','게임 스마트키를 삽입하고 출구 토큰을 확인한다.','게임 시동 버튼을 누르면 시설 탈출 연출이 시작된다.'];}
function playEnding(replay=false){endingActive=true;terminalRefresh=null;closeModal(false);stopRecording();if(archivePlayer)archivePlayer.pause();setGameInert(true);const complete=f().gameComplete,act2=!complete&&f().frameToken;$('#ending').classList.add('visible');$('#ending').setAttribute('aria-label',complete?'탈출 성공':act2?'2막 완료':'1막 완료');$('#end-art').src=u('assets/backgrounds/'+(complete?'FINAL':act2?'S11':'END')+'.png');$('#end-art').alt=complete?'열린 시설 출구와 새벽, 탈출하는 차량':act2?'프레임 04로 돌아온 운전석':'비에 젖은 운송 프레임과 비어 있는 마지막 공간';$('#end-labels').innerHTML='';const caption=$('#ending-caption');caption.innerHTML=`<div class="eyebrow">${complete?'ESCAPE COMPLETE':act2?'CHAPTER 02 COMPLETE':'CHAPTER 01 COMPLETE'}</div><h2>${complete?'탈출 성공.':act2?'이제, 돌아갈 차례다.':'차 밖에 나왔다.'}</h2><p>${complete?'구조 명단 수신 확인.<br>윤서: “이번에는 기억해.”':act2?'회수된 열쇠와 토큰. 준비한 흔적이 기다리고 있다.':'감시실에 남은 다섯 번째 기록을 찾아야 한다.'}</p><button id="end-next" class="action primary">${complete?'마지막 장면 다시 보기':act2?'3막 · 마지막 시동':'2막 · 누락된 기록'}</button><button id="end-records-v2" class="action">진행 기록</button>`;$('#end-next').onclick=()=>complete?playEnding(true):continueAct(act2?3:2);$('#end-records-v2').onclick=endRecords;caption.classList.remove('shown');caption.inert=true;$('#ending').style.opacity='0';$('#app').classList.toggle('escaping',complete&&!replay);fitEnding();setTimeout(()=>{if(!endingActive)return;$('#ending').style.opacity='1';$('#app').classList.remove('escaping');},replay?100:complete?1300:450);setTimeout(()=>{if(!endingActive)return;caption.classList.add('shown');caption.inert=false;if(complete)playArchive('final');},complete?2800:1400);save();}
function continueAct(n){endingActive=false;$('#ending').classList.remove('visible');outcome(game.dispatch('nextAct',n));setGameInert(false);syncPaused();terminalRefresh=null;save();}
function endRecords(){showModal(f().gameComplete?'탈출의 기록':'현재까지의 기록',`<div class="note-grid"><article class="note"><h3>현재 막</h3><p>${game.state.chapter} / 3</p></article><article class="note"><h3>완료한 퍼즐</h3><p>${game.state.completedPuzzles.length} / 15</p></article><article class="note"><h3>플레이 시간</h3><p>${formatTime(game.state.elapsedSec)}</p></article></div><p class="subtle">45–60분은 설계 목표이며, 실제 이용자 소요 시간은 플레이 테스트로 조정해야 합니다.</p>`,[{label:'돌아가기',primary:true,run:()=>closeModal()},{label:'새 게임',run:confirmNewGame}],'records','RESIDUAL POWER / FIELD RECORD');}
