// Menus freeze unfinished stable holds. Scene changes detach the previous terminal.
function syncPaused(){
 const pause=menuPause||externalPause,was=game.runtime.paused;
 if(pause&&!was)game.input.suspend(Date.now(),externalPause);
 else if(!pause&&was&&!game.input.resume())checkSafety();
 syncPausedLegacy();
}
function sceneTo(id){
 const destination=CONTENT.scenes.find(x=>x.id===id&&x.chapter<=game.state.chapter);
 if(destination&&id!==game.state.currentScreen){game.input.disarm();terminalRefresh=null;activeInputView=null;}
 sceneToLegacy(id);
}

